'use client';

import React from 'react';
import FaqCategory from './FaqCategory';
import { FAQS } from '@/constants';
import Link from 'next/link';

interface AllFaqsProps {
    industryFaqs?: {
        name: string;
        slug: string;
        faqs: { question: string; answer: string }[];
    }[];
}

const AllFaqs: React.FC<AllFaqsProps> = ({ industryFaqs = [] }) => {
    return (
        <section className="py-20 bg-brand-bg-main min-h-screen">
            <div className="container mx-auto px-4 sm:px-6 lg:px-8 max-w-6xl">

                {/* Navigation Pills */}
                <div className="flex flex-wrap gap-2 justify-center mb-16 border-b border-gray-100 pb-8 sticky top-20 bg-brand-bg-main/95 backdrop-blur-sm z-30 py-4 transition-all">
                    <a href="#general" className="px-6 py-2 rounded-full bg-brand-primary/5 text-brand-primary font-bold text-sm hover:bg-brand-primary hover:text-white transition-all">General</a>
                    {industryFaqs.length > 0 && (
                        <a href="#industries" className="px-6 py-2 rounded-full bg-white border border-gray-200 text-brand-gray font-bold text-sm hover:border-brand-primary hover:text-brand-primary transition-all">Industries</a>
                    )}
                </div>

                <div className="space-y-8">
                    <FaqCategory
                        id="general"
                        title="General Queries"
                        description="Basics about Logic-unit, our operational models, and partnership details."
                        faqs={FAQS}
                    />

                    {industryFaqs.length > 0 && (
                        <div id="industries">
                            <h2 className="text-3xl font-bold font-heading text-brand-dark mb-8 mt-16 border-b border-gray-200 pb-4">
                                Industry Specific FAQs
                            </h2>
                            <div className="space-y-12">
                                {industryFaqs.map((industry) => (
                                    <FaqCategory
                                        key={industry.slug}
                                        id={`industry-${industry.slug}`}
                                        title={industry.name}
                                        faqs={industry.faqs}
                                    />
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                <div className="mt-20 p-10 bg-brand-dark rounded-3xl text-center text-white relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-brand-primary/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
                    <div className="absolute bottom-0 left-0 w-64 h-64 bg-brand-secondary/10 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2"></div>

                    <div className="relative z-10">
                        <h3 className="text-2xl md:text-3xl font-bold font-heading mb-4">Still have questions?</h3>
                        <p className="text-gray-400 mb-8 max-w-xl mx-auto">
                            Our team is strictly available to answer any technical or business related inquiry. We usually respond within 24 hours.
                        </p>
                        <Link href="/contact" className="inline-flex items-center justify-center rounded-full font-bold px-8 py-3 bg-white text-brand-dark hover:bg-brand-primary hover:text-white transition-all duration-300">
                            Get in Touch
                        </Link>
                    </div>
                </div>
            </div>
        </section>
    );
};

export default AllFaqs;
